mapper.sql:
pr.applicant_id = #{criteria.applicantId}

    AND pr.status = #{criteria.status}


    AND (
        pr.request_number ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
        OR pr.title ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
        OR EXISTS (
            SELECT 1
            FROM request_items searched_item
            WHERE searched_item.request_id = pr.id
              AND (
                  searched_item.product_name ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
                  OR searched_item.model_number ILIKE ('%' || #{criteria.keyword} || '%') ESCAPE '\'
              )
        )
    )


    AND pr.created_at >= #{criteria.createdFrom}


    AND pr.created_at < #{criteria.createdToExclusive}


    AND EXISTS (
        SELECT 1
        FROM request_items category_item
        WHERE category_item.request_id = pr.id
          AND category_item.category_id = #{criteria.categoryId}
    )


    AND pr.requested_supplier_id = #{criteria.supplierId}
